package local.ziweixingyu.rebuild;
import android.widget.*;
import android.text.InputType;
import java.util.*;
import org.json.*;

final class FlowController {
 final MainActivity host;int mode=0,age=1,month=1;JSONObject data,decadal,annual;String source="";boolean lines=true;EditText ageInput;TextView heading,details,period;MainActivity.ChartView canvas;final Button[] modeButtons=new Button[4];
 LinearLayout months,dayHourControls;Spinner monthInput;
 int day=1,hour=0;boolean showDayHour=false;JSONObject dayHour;CheckBox dayHourToggle;Button dayHourButton;
 FlowController(MainActivity host){this.host=host;}
 void reset(JSONObject chart){mode=0;month=1;day=1;hour=0;showDayHour=false;dayHour=null;data=null;decadal=null;annual=null;source="";try{age=Math.max(1,Math.min(120,Calendar.getInstance(TimeZone.getTimeZone("GMT+8")).get(Calendar.YEAR)-Integer.parseInt(chart.getJSONObject("其他信息").getString("农历年"))+1));}catch(Exception e){age=1;}}
 void attach(LinearLayout content,MainActivity.ChartView view){canvas=view;LinearLayout box=host.column();box.setPadding(host.dp(8),host.dp(4),host.dp(8),host.dp(8));content.addView(box);
  LinearLayout modes=host.row();String[] names={"本命","大限","流年","流月"};for(int i=0;i<4;i++){final int chosen=i;modeButtons[i]=host.button(names[i],()->select(chosen));modes.addView(modeButtons[i],new LinearLayout.LayoutParams(0,host.dp(44),1));}box.addView(modes);
  LinearLayout years=host.row();years.addView(host.text("虚岁",14,MainActivity.INK),new LinearLayout.LayoutParams(host.dp(38),host.dp(44)));years.addView(host.button("−",()->step(-1)),new LinearLayout.LayoutParams(host.dp(46),host.dp(44)));
  ageInput=host.edit(String.valueOf(age),"1—120",InputType.TYPE_CLASS_NUMBER);years.addView(ageInput,new LinearLayout.LayoutParams(0,host.dp(44),1));years.addView(host.button("+",()->step(1)),new LinearLayout.LayoutParams(host.dp(46),host.dp(44)));years.addView(host.button("应用",()->apply()),new LinearLayout.LayoutParams(host.dp(68),host.dp(44)));box.addView(years);
  months=host.row();months.addView(host.text("农历月",14,MainActivity.INK),new LinearLayout.LayoutParams(host.dp(64),host.dp(44)));months.addView(host.button("上月",()->changeMonth(-1)),new LinearLayout.LayoutParams(host.dp(68),host.dp(44)));monthInput=new Spinner(host);ArrayAdapter<String> adapter=new ArrayAdapter<>(host,android.R.layout.simple_spinner_item,MonthState.MONTHS);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);monthInput.setAdapter(adapter);monthInput.setSelection(month-1);months.addView(monthInput,new LinearLayout.LayoutParams(0,host.dp(44),1));months.addView(host.button("下月",()->changeMonth(1)),new LinearLayout.LayoutParams(host.dp(68),host.dp(44)));box.addView(months);monthInput.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,android.view.View v,int pos,long id){if(month!=pos+1){month=pos+1;showDayHour=false;clearSource();refresh();}}});
  dayHourControls=host.row();dayHourToggle=new CheckBox(host);dayHourToggle.setText("日时叠宫");dayHourToggle.setTextSize(14);dayHourToggle.setChecked(showDayHour);dayHourToggle.setOnCheckedChangeListener((b,on)->{if(showDayHour!=on){showDayHour=on;refresh();}});dayHourControls.addView(dayHourToggle,new LinearLayout.LayoutParams(0,host.dp(48),1));dayHourButton=host.button("选择日时",()->queryDayHour());dayHourControls.addView(dayHourButton,new LinearLayout.LayoutParams(0,host.dp(48),1));dayHourControls.addView(host.button("公历换算",()->CalendarDialog.show(this)),new LinearLayout.LayoutParams(0,host.dp(48),1));box.addView(dayHourControls);
  LinearLayout options=host.row();CheckBox showLines=new CheckBox(host);showLines.setText("四化连线");showLines.setTextSize(14);showLines.setChecked(lines);showLines.setOnCheckedChangeListener((b,on)->{lines=on;canvas.invalidate();host.rememberSession(false);});options.addView(showLines,new LinearLayout.LayoutParams(0,host.dp(44),1));options.addView(host.button("回到命宫",()->{clearSource();refresh();}),new LinearLayout.LayoutParams(0,host.dp(44),1));options.addView(host.button("按年份",()->queryYear()),new LinearLayout.LayoutParams(0,host.dp(44),1));box.addView(options);
  heading=host.text("",15,MainActivity.TEAL);box.addView(heading);period=host.text("",13,MainActivity.TEAL);box.addView(period);details=host.text("",14,MainActivity.INK);details.setTextIsSelectable(true);box.addView(details);refresh();
 }
 JSONObject snapshot()throws JSONException{return new JSONObject().put("mode",mode).put("age",age).put("month",month).put("day",day).put("hour",hour).put("dayHour",showDayHour).put("lines",lines).put("source",source).put("selected",host.selectedPalace);}
 void restore(JSONObject v){mode=v.optInt("mode");age=v.optInt("age");month=v.optInt("month");day=v.optInt("day");hour=v.optInt("hour");showDayHour=v.optBoolean("dayHour");lines=v.optBoolean("lines");source=v.optString("source");host.selectedPalace=v.optString("selected");}
 void clearSource(){source="";host.selectedPalace="";if(canvas!=null)canvas.selected=-1;host.updatePalaceDetail();}
 void select(int selected){mode=selected;showDayHour=false;clearSource();refresh();}
 void chooseSource(String branch){if(data==null||data.optJSONObject("palaces").length()==0)return;source=branch;refresh();}
 void cycle(){select((mode+1)%4);}
 void changeMonth(int direction){try{month=MonthState.step(month,direction);showDayHour=false;monthInput.setSelection(month-1);clearSource();refresh();}catch(Exception e){host.message("月份未切换",e.getMessage());}}
 void queryDayHour(){
  if(mode!=3||data==null)return;
  LinearLayout box=host.column();box.setPadding(host.dp(20),host.dp(8),host.dp(20),0);
  box.addView(host.text("输入已知的农历日与时辰，仅叠加日、时宫位；四化来源不变。可用公历换算辅助填写；手选值未校验闰月与大小月。",14,MainActivity.INK));
  box.addView(host.text("农历日（1—30）",14,MainActivity.INK));EditText input=host.edit(String.valueOf(day),"如20",InputType.TYPE_CLASS_NUMBER);input.setContentDescription("叠宫农历日");box.addView(input);
  box.addView(host.text("时辰",14,MainActivity.INK));Spinner hours=new Spinner(host);String[] names=new String[12];for(int i=0;i<12;i++)names[i]=FlowState.BRANCH.substring(i,i+1)+"时";ArrayAdapter<String> adapter=new ArrayAdapter<>(host,android.R.layout.simple_spinner_item,names);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);hours.setAdapter(adapter);hours.setSelection(hour);hours.setContentDescription("叠宫时辰");box.addView(hours,new LinearLayout.LayoutParams(-1,host.dp(48)));
  TextView error=host.text("",14,MainActivity.RED);error.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);error.setVisibility(android.view.View.GONE);box.addView(error);
  ScrollView scroll=new ScrollView(host);scroll.addView(box);
  android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(host).setTitle("选择日时叠宫").setView(scroll).setNegativeButton("取消",null).setPositiveButton("查看",null).create();
  dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{int next=DayHourState.parseDay(input.getText().toString());int nextHour=hours.getSelectedItemPosition();DayHourState.describe(data,next,FlowState.BRANCH.substring(nextHour,nextHour+1));day=next;hour=nextHour;showDayHour=true;refresh();((android.view.inputmethod.InputMethodManager)host.getSystemService(android.content.Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);dialog.dismiss();}catch(Exception e){error.setText(e.getMessage());error.setVisibility(android.view.View.VISIBLE);}}));dialog.show();
 }
 String dayHourTitle(){return dayHour==null?"":"手选日时 · "+dayHour.optString("dayName")+" "+dayHour.optString("hour")+"时 · 日命"+dayHour.optString("dayAnchor")+" / 时命"+dayHour.optString("hourAnchor");}
 String dayHourSummary(){if(dayHour==null)return "";StringBuilder out=new StringBuilder("\n\n"+dayHourTitle()+"\n仅叠宫，四化来源不变；未校验闰月与大小月。\n");for(int i=0;i<12;i++){String b=FlowState.BRANCH.substring(i,i+1);out.append(b).append("：日").append(dayHour.optJSONObject("dayPalaces").optString(b)).append(" / 时").append(dayHour.optJSONObject("hourPalaces").optString(b)).append('\n');}return out.toString().trim().isEmpty()?"":"\n\n"+out.toString().trim();}
 void queryYear(){
  int year;try{year=FlowState.describe(host.chart,true,age).getInt("year");}catch(Exception e){host.message("年份查询未打开",e.getMessage());return;}
  LinearLayout box=host.column();box.setPadding(host.dp(20),host.dp(8),host.dp(20),0);
  box.addView(host.text("按农历年份编号定位，自动换算虚岁。保留当前月份；本命模式会转到流年。",14,MainActivity.INK));
  EditText input=host.edit(String.valueOf(year),"如2027",InputType.TYPE_CLASS_NUMBER);input.setContentDescription("查询年份");box.addView(input);
  TextView error=host.text("",14,MainActivity.RED);error.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);error.setVisibility(android.view.View.GONE);box.addView(error);
  android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(host).setTitle("按年份查询").setView(box).setNegativeButton("取消",null).setPositiveButton("查询",null).create();
  dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{int next=FlowState.ageForYear(host.chart,input.getText().toString());age=next;showDayHour=false;if(mode==0)mode=2;ageInput.setText(String.valueOf(age));ageInput.setError(null);clearSource();refresh();((android.view.inputmethod.InputMethodManager)host.getSystemService(android.content.Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);dialog.dismiss();}catch(Exception e){error.setText(e.getMessage());error.setVisibility(android.view.View.VISIBLE);}}));dialog.show();
 }
 void apply(){try{int next=Integer.parseInt(ageInput.getText().toString());if(next<1||next>120)throw new Exception();age=next;showDayHour=false;clearSource();ageInput.setError(null);((android.view.inputmethod.InputMethodManager)host.getSystemService(android.content.Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(ageInput.getWindowToken(),0);refresh();}catch(Exception e){ageInput.setError("请输入1至120的虚岁");}}
 void step(int direction){try{age=FlowState.step(host.chart,mode!=1,age,direction);showDayHour=false;clearSource();ageInput.setText(String.valueOf(age));ageInput.setError(null);refresh();}catch(Exception e){host.message("暂时无法切换",e.getMessage());}}
 void refresh(){for(int i=0;i<4;i++){modeButtons[i].setSelected(i==mode);modeButtons[i].setTextColor(i==mode?android.graphics.Color.WHITE:MainActivity.INK);modeButtons[i].setBackgroundTintList(android.content.res.ColorStateList.valueOf(i==mode?MainActivity.TEAL:0xffeeeeee));}try{data=mode==0?null:mode==3?MonthState.describe(host.chart,age,month):FlowState.describe(host.chart,mode==2,age);decadal=mode>=2?FlowState.describe(host.chart,false,age):null;annual=mode==3?FlowState.describe(host.chart,true,age):null;months.setVisibility(mode==3?android.view.View.VISIBLE:android.view.View.GONE);if(data!=null&&!source.isEmpty())data=FlowState.selectSource(host.chart,data,source);dayHour=mode==3&&showDayHour?DayHourState.describe(data,day,FlowState.BRANCH.substring(hour,hour+1)):null;dayHourControls.setVisibility(mode==3?android.view.View.VISIBLE:android.view.View.GONE);dayHourToggle.setChecked(showDayHour);dayHourButton.setText("选择日时");heading.setText(data==null?"本命命盘":data.getString("title"));period.setText((annual==null?"":annual.getString("title")+"\n")+(decadal==null?"":decadal.getString("title"))+(mode==3?"\n按月序查看，暂不区分当年闰月":""));period.setVisibility(decadal==null?android.view.View.GONE:android.view.View.VISIBLE);details.setText(data==null?"点击圆盘可切换本命、大限、流年、流月。":summaryBody()+(dayHour==null?"":"\n\n"+dayHourTitle()+"\n仅叠宫，四化来源不变；未校验闰月与大小月。"));canvas.setContentDescription("紫微十二宫命盘 · "+heading.getText()+(decadal==null?"":" · 同时叠加"+decadal.optString("title"))+(data==null?"":" · 四化来源"+data.optString("source",data.optString("anchor")))+(dayHour==null?"":" · "+dayHourTitle()));canvas.invalidate();host.rememberSession(false);}catch(Exception e){data=null;decadal=null;annual=null;dayHour=null;heading.setText("流运未生成");period.setVisibility(android.view.View.GONE);details.setText(e.getMessage());canvas.invalidate();}}
 String summaryBody(){if(data==null)return "";StringBuilder out=new StringBuilder(prefix()+data.optString("sourceLabel","命")+"在"+data.optString("source",data.optString("anchor"))+" · "+data.optString("stem")+"干四化\n");JSONObject t=data.optJSONObject("transforms");if(t.length()==0)return "尚未进入首限，可调整虚岁或查看流年。";
  for(String mark:new String[]{"禄","权","科","忌"})for(Iterator<String> it=t.keys();it.hasNext();){String star=it.next();JSONObject v=t.optJSONObject(star);if(mark.equals(v.optString("化")))out.append(star).append("化").append(mark).append(" → ").append(v.optString("支")).append(v.optString("流宫")).append("宫").append(v.has("力度")?"（"+v.optInt("力度")+"%）":"（力度未确认）").append('\n');}return out.toString().trim();
 }
 String summary(){return data==null?"":"\n\n"+data.optString("title")+"\n"+(annual==null?"":"同时叠加："+annual.optString("title")+"\n")+(decadal==null?"":"同时叠加："+decadal.optString("title")+"\n")+summaryBody()+monthSummary()+dayHourSummary();}
 String overlay(String branch){return data==null?"":data.optJSONObject("palaces").optString(branch,"");}
 String prefix(){return mode==1?"限":mode==3?"月":"年";}
 String monthSummary(){if(mode!=3||data==null)return "";StringBuilder text=new StringBuilder("\n月份分布（不区分当年闰月）\n");JSONObject map=data.optJSONObject("monthMap");for(int m=1;m<=12;m++)for(int i=0;i<12;i++){String b=FlowState.BRANCH.substring(i,i+1);JSONObject item=map.optJSONObject(b);if(item.optInt("month")==m)text.append(item.optString("name")).append(item.optString("stem")).append("：").append(b).append("宫\n");}return text.toString().trim().isEmpty()?"":"\n"+text.toString().trim();}
}
